// ASYNC

export const preprocessHeraFile = async (
		path: string,
		tempPath: (string | undefined) = undef
		): AutoPromise<[string, THeraType]> => {

	const {hMetaData, reader} = openTextFile(path)
	const type = mdGet(hMetaData, 'type', 'civet')
	assert(isHeraType(type), `Bad hera type: ${type}`)
	const heraCode = preprocessHera(reader, type)
	if (defined(tempPath)) {
		await Deno.writeTextFile(tempPath, heraCode)
	}
	return [heraCode, type]
}

// ---------------------------------------------------------------------------

const buildHeraFile = (
		lMainCode: string[],
		lResetCode: string[],
		ruleSet: CRuleSet,
		type: THeraType,
		debug: boolean = false
		) => {

	debugger
	const mainCode = mkCodeBlock(lMainCode, type)
	if (debug) {
		DUMP(mainCode, 'mainCode')
	}

	const resetCode = mkCodeBlock(lResetCode, type)
	if (debug) {
		DUMP(resetCode, 'resetCode')
	}

	const lRuleBlocks = ruleSet.lRules.map((rule) => rule.toString(type))
	if (debug) {
		let i1 = 0;for (const block of lRuleBlocks) {const i = i1++;
			DUMP(block, `Rule[${i}]`)
		}
	}

	let lParts: string[] = []
	lParts.push(
		"```",
		"import {CParseMatches} from 'parse-utils';",
		"export let pm = new CParseMatches();",
		"")
	if (nonEmpty(mainCode)) {
		lParts.push(mainCode, "")
	}

	lParts.push(
		"export const beginParse = (text: string): void => {",
		indented("pm.reset(text);"),
		indented(resetCode),
		indented('}'),
		"```",
		'',
		...lRuleBlocks)
	const result = lParts.join('\n').replaceAll('\t', spaces(2))
	if (debug) {
		DUMP(result, 'Result')
	}
	return result
}

// ---------------------------------------------------------------------------

export const decom = (line: string): string => {

	return line.replace(/^(\s*)#(\s)/, "$1//$2")
}

// ---------------------------------------------------------------------------

export const preprocessHera = (
		iter: string | TIterator<string>,
		type: THeraType = 'typescript',
		debug: boolean = false
		): string => {

	debugger
	if (isString(iter)) {
		iter = allLinesInBlock(iter)
	}
	resetOneIndent()

	const lMainCode:  string[] = []
	const lResetCode: string[] = []

	const ruleSet = new CRuleSet()

	const result = fromFSM(iter, [

		// 0 --- start
		//          until we see #beginParse, everything, including
		//          blank lines, goes into main code

		(line: string): TState => {
			if (line === '#beginParse') {
				return 1
			}
			else {
				lMainCode.push(decom(line))
				return 0
			}
		},

		// 1 --- in beginParse function
		//          until we see a rule name, everything, including
		//          blank lines, goes into reset code

		(line: string): TState => {
			const [level, str] = splitLine(line)
			if (nonEmpty(str) && (level === 0)) {
				ruleSet.addRule(str)
				return 2
			}
			else {
				if (isEmpty(str) && (level === 0)) {
					lResetCode.push('')
				}
				else {
					lResetCode.push(indented(decom(str), level-1))
				}
				return 1
			}
		},

		// 2 --- have rule, want pattern
		//          skip blank lines, but expect a pattern at level 1

		(line: string, i: number): TState => {
			const [level, pat] = splitLine(line)
			if ((level === 0) && (pat === '')) {
				return 2
			}
			assert((level === 1),
				`Expecting pattern for rule ${ruleSet.ruleName()} on line ${i}`)
			ruleSet.addBranch(pat)
			ruleSet.addCode(`pm.match('${ruleSet.ruleName()}', $loc);`)
			return 3
		},

		// 3 --- have pattern, want code
		//          ignore blank lines

		(line: string, i: number): TState => {
			const [level, str] = splitLine(line)
			switch(level) {
				case 0: {
					if (str === '') {
						return 3
					}
					else {
						ruleSet.addRule(str)
						return 2
					}
				}
				case 1: {
					ruleSet.addBranch(str)
					return 2
				}
				default: {
					// --- first line of code must be at level 2
					if (ruleSet.curRule().numCodeLines() === 0) {
						assert((level === 2), "First line of code must be level 2")
					}
					ruleSet.addCode(indented(decom(str), level-2))
					return 3
				}
			}
		}

		], (state: TState): void => {
			if (state === 3) {
				const str = buildHeraFile(lMainCode, lResetCode, ruleSet, type, debug)
				throw str
			}
			else {
				croak(`Ended in state ${state}`)
			}
	})
	assert((typeof result === 'string'), "result not a string")
	return result
}

